// Read a shareable hash route and fall back safely for unknown locations.
function readRoute() {
  const [section = "overview", id = ""] = location.hash.slice(1).split("/");
  return { section: section in sectionNames ? section : "overview", id };
}

// Return a timestamp for local review and activity records.
function localTime() {
  return new Date().toLocaleString("zh-CN", { hour12: false });
}

// Present a compact, reusable row with a single accessible touch target.
function ActionRow({
  icon,
  title,
  detail,
  trailing,
  onClick,
}: {
  icon: ReactNode;
  title: string;
  detail?: string;
  trailing?: ReactNode;
  onClick: () => void;
}) {
  return (
    <button className="m-row" onClick={onClick}>
      <span className="m-row-icon">{icon}</span>
      <span className="m-row-copy">
        <strong>{title}</strong>
        {detail && <small>{detail}</small>}
      </span>
      {trailing}
      <ChevronRight size={17} />
    </button>
  );
}

